	private static Join observed() {
		Join observed = new Join(sp("page", P1, "review"), sp("review", P2, "award"));
		Distinct root = new Distinct(observed);
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		observed.setCostFeedbackTrackingEnabled(true);
		observed.setCostFeedbackExpectedRows(100.0d);
		observed.setCostFeedbackExpectedWorkRows(1_000.0d);
		observed.setResultSizeEstimate(100.0d);
		observed.setCostEstimate(1_000.0d);
		observed.setCostFeedbackActualRows(400L);
		observed.setCostFeedbackActualWorkRows(650.0d);
		observed.setCostFeedbackCloseCountActual(1L);
		observed.setCostFeedbackCompletedActual(true);
		observed.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
		observed.setStringMetricPlanned("optimizer.frontierLearningKey", KEY.externalForm());
		observed.setStringMetricPlanned("optimizer.costEventDigest", "event-deferred");
		observed.setStringMetricPlanned("optimizer.frontierStateDigest", "state-deferred");
		observed.setStringMetricPlanned("plannedFrontierGuarantee", "measure_unbiased");
		return observed;
	}

	private static StatementPattern sp(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("p", predicate, true, true), Var.of(object));
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		HeldStore(Path path, CountDownLatch entered, CountDownLatch release) {
			super(path.toFile(), config());
			this.entered = entered;
			this.release = release;
		}

		private static LmdbStoreConfig config() {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
			config.setExperimentalQueryOptimizations(true);
			return config;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
